void dst_bus_ign_on (void * arg)
{ 
  if(!dst_bus_vars.flg_ign)
    {
      dst_bus_vars.flg_ign  = TRUE  ;
      
      DST_BUS_READER_RX_INT_CLR ; //dst_bus_reader_int_clr    ()  ;
      DST_BUS_INT_ENA           ; //dst_bus_reader_ena        ()  ;   
      
      #if DBG_DST_BUS == 1
        dst_bus_dbg_print ("\nDst Bus Ign On", NULL , NULL) ;
      #endif
      TRACE ("\r\nDST BUS IGN ON\r\n");
        
    }
}
